// Signs a request to Convex: HMAC-SHA256 over `${timestamp}.${rawBody}` with
// LENDLOOP_INBOUND_SECRET, read from the container env (n8n/.env), never stored here.
const crypto = require('crypto');
function signed(body) {
  const raw = body === undefined ? '' : JSON.stringify(body);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto
    .createHmac('sha256', $env.LENDLOOP_INBOUND_SECRET)
    .update(`${timestamp}.${raw}`)
    .digest('hex');
  return { raw, timestamp, signature };
}

// GET has no body, so the signature covers `${timestamp}.` only.
return [{ json: signed(undefined) }];

// One item per overdue loan. Convex already left out loans reminded today,
// so re-running this workflow doesn't email anyone twice.
const { loans } = $input.first().json;
return loans.map((loan) => ({ json: loan }));

// Signs a request to Convex: HMAC-SHA256 over `${timestamp}.${rawBody}` with
// LENDLOOP_INBOUND_SECRET, read from the container env (n8n/.env), never stored here.
const crypto = require('crypto');
function signed(body) {
  const raw = body === undefined ? '' : JSON.stringify(body);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto
    .createHmac('sha256', $env.LENDLOOP_INBOUND_SECRET)
    .update(`${timestamp}.${raw}`)
    .digest('hex');
  return { raw, timestamp, signature };
}

// Reports each reminder's outcome. idempotencyKey (reminder:<loanId>:<date>)
// came from Convex, so a retried write-back never creates a second record.
const loan = $('Split overdue loans').item.json;
const error = $json.error;
const failed = error !== undefined;
return {
  json: signed({
    loanId: loan.loanId,
    idempotencyKey: loan.idempotencyKey,
    status: failed ? 'failed' : 'sent',
    detail: failed
      ? String(error?.message ?? error).slice(0, 500)
      : `Reminder emailed (${loan.daysOverdue} day${loan.daysOverdue === 1 ? '' : 's'} overdue)`,
  }),
};
